  "scores": [
    {
      "Type": "Gate",
      "Criterion": "Open Weights",
      "Default Weight / Rule": "Required",
      "How to Use": "Exclude models without downloadable weights."
    },
    {
      "Type": "Gate",
      "Criterion": "Commercial Local Verdict",
      "Default Weight / Rule": "Required",
      "How to Use": "Exclude No; review Conditional before shipping."
    },
    {
      "Type": "Gate",
      "Criterion": "Runs on Target Hardware",
      "Default Weight / Rule": "Required",
      "How to Use": "Configuration must fit target-user RAM/VRAM/unified memory."
    },
    {
      "Type": "Score",
      "Criterion": "Quality",
      "Default Weight / Rule": "35%",
      "How to Use": "Normalize within the same modality using relevant benchmark(s)."
    },
    {
      "Type": "Score",
      "Criterion": "Interactive Speed",
      "Default Weight / Rule": "25%",
      "How to Use": "Use TTFT/time-to-first-output plus throughput/RTF appropriate to the modality."
    },
    {
      "Type": "Score",
      "Criterion": "Memory Footprint",
      "Default Weight / Rule": "15%",
      "How to Use": "Prefer configurations that leave memory headroom."
    },
    {
      "Type": "Score",
      "Criterion": "Runtime / Platform Coverage",
      "Default Weight / Rule": "10%",
      "How to Use": "Reward stable support for platforms your users own."
    },
    {
      "Type": "Score",
      "Criterion": "Model Size / Download",
      "Default Weight / Rule": "5%",
      "How to Use": "Smaller downloads improve installation/update UX."
    },
    {
      "Type": "Score",
      "Criterion": "License Simplicity",
      "Default Weight / Rule": "5%",
      "How to Use": "Prefer clear permissive rights and simple redistribution obligations."
    },
    {
      "Type": "Score",
      "Criterion": "Operational Features",
      "Default Weight / Rule": "5%",
      "How to Use": "Streaming, offline, batching, quantization support, runtime maturity."
    }
  ],
  "flowColumns": [
    "Step",
    "Rule",
    "Why",
    "Result"
  ],
  "flow": [
    {
      "Step": "1",
      "Rule": "Open Weights = Yes",
      "Why": "Project scope",
      "Result": "Open-weight pool"
    },
    {
      "Step": "2",
      "Rule": "Commercial Local Verdict = Yes/Reviewed Conditional",
      "Why": "Legal rights are a gate, not a soft score",
      "Result": "Commercially eligible pool"
    },
    {
      "Step": "3",
      "Rule": "Fits selected Hardware Profile",
      "Why": "A model must fit user's memory and supported runtime",
      "Result": "Hardware-compatible pool"
    },
    {
      "Step": "4",
      "Rule": "Normalize quality within modality",
      "Why": "LLM/TTS/STT/Image/etc. quality scales differ",
      "Result": "Quality 0-100"
    },
    {
      "Step": "5",
      "Rule": "Normalize speed on comparable hardware/configuration",
      "Why": "Different hardware cannot be mixed blindly",
      "Result": "Speed 0-100"
    },
    {
      "Step": "6",
      "Rule": "Apply weighted score",
      "Why": "35% quality, 25% speed, 15% memory, 10% platform, 5% size, 5% license, 5% features",
      "Result": "Local Suitability 0-100"
    }
  ],
